import { describe, expect, it } from 'vitest';
import type { NoteDocument } from './api/types';
import { blockPlainText, documentsEqual, normalizeDocument } from './noteDocument';
import { fromProseMirror, toProseMirror } from './tiptapDocument';

/**
 * The stored document is the only shape we persist, so a trip through the editor has to come back
 * unchanged. `documentsEqual` ignores block ids on purpose — those are regenerated by the
 * conversion — which is exactly what these tests lean on.
 */

/** The tests are about the first line; this keeps the index access honest under strict TS. */
function firstLine(document: NoteDocument) {
  const block = document.blocks[0];
  if (!block) throw new Error('expected at least one block');
  return block;
}

function document(...blocks: Array<[string, string?, Record<string, unknown>?]>): NoteDocument {
  return normalizeDocument({
    version: 1,
    blocks: blocks.map(([type, text, extra], index) => ({
      id: `b${index}`,
      type: type as never,
      spans: text ? [{ text }] : [],
      ...(extra && 'checked' in extra ? { checked: extra.checked as boolean } : {}),
      ...(extra && 'depth' in extra ? { depth: extra.depth as number } : {})
    }))
  });
}

describe('a note survives the trip through the editor', () => {
  const cases: Array<[string, NoteDocument]> = [
    ['a single empty line', document(['paragraph'])],
    ['plain paragraphs', document(['paragraph', 'first'], ['paragraph', 'second'])],
    ['headings at each level', document(['heading1', 'one'], ['heading2', 'two'], ['heading3', 'three'])],
    ['a bulleted list', document(['bulleted', 'one'], ['bulleted', 'two'])],
    [
      'a nested checklist',
      document(['checklist', 'parent'], ['checklist', 'child', { checked: true, depth: 1 }], ['checklist', 'top'])
    ],
    ['a numbered list', document(['numbered', 'one'], ['numbered', 'two'])],
    ['a checklist with both states', document(['checklist', 'done', { checked: true }], ['checklist', 'todo', { checked: false }])],
    ['a list interrupted by a paragraph', document(['bulleted', 'one'], ['paragraph', 'text'], ['bulleted', 'two'])],
    ['a bulleted list followed by a numbered one', document(['bulleted', 'one'], ['numbered', 'two'])]
  ];

  for (const [name, original] of cases) {
    it(`keeps ${name}`, () => {
      // given: the document as it is stored
      // when
      const back = fromProseMirror(toProseMirror(original));

      // then: the same blocks, in the same order, with the same state
      expect(documentsEqual(original, back), JSON.stringify(back)).toBe(true);
    });
  }

  it('keeps inline styling', () => {
    // given
    const original = document([
      'paragraph',
      'plain',
      undefined
    ]);
    original.blocks = [
      {
        id: 'b0',
        type: 'paragraph',
        spans: [
          { text: 'bold', bold: true },
          { text: ' and ' },
          { text: 'italic', italic: true },
          { text: ' and ' },
          { text: 'under', underline: true },
          { text: ' and ' },
          { text: 'struck', strikethrough: true },
          { text: ' and ' },
          { text: 'code', code: true },
          { text: ' and ' },
          { text: 'link', link: 'https://example.com' }
        ]
      }
    ];

    // when
    const back = fromProseMirror(toProseMirror(original));

    // then
    expect(documentsEqual(original, back), JSON.stringify(back)).toBe(true);
    expect(firstLine(back).spans.map((span) => span.text).join('')).toBe(
      'bold and italic and under and struck and code and link'
    );
  });

  it('keeps a nested list nested', () => {
    // given: an editor list with a list inside one of its items
    const json = {
      type: 'doc',
      content: [
        {
          type: 'bulletList',
          content: [
            {
              type: 'listItem',
              content: [
                { type: 'paragraph', content: [{ type: 'text', text: 'outer' }] },
                {
                  type: 'bulletList',
                  content: [
                    {
                      type: 'listItem',
                      content: [
                        { type: 'paragraph', content: [{ type: 'text', text: 'inner' }] },
                      ]
                    }
                  ]
                }
              ]
            }
          ]
        }
      ]
    };

    // when
    const back = fromProseMirror(json);

    // then: each line keeps the level it sat at
    expect(back.blocks.map((block) => [blockPlainText(block), block.depth])).toEqual([
      ['outer', 0],
      ['inner', 1],
    ]);

    // and: going back produces the same nesting
    expect(documentsEqual(back, fromProseMirror(toProseMirror(back)))).toBe(true);
  });

  it('pulls an over-indented line up to a level that exists', () => {
    // given: our format cannot jump two levels at once
    const json = {
      type: 'doc',
      content: [
        {
          type: 'bulletList',
          content: [
            {
              type: 'listItem',
              content: [
                { type: 'paragraph', content: [{ type: 'text', text: 'first' }] },
                {
                  type: 'bulletList',
                  content: [
                    { type: 'listItem', content: [{ type: 'paragraph', content: [{ type: 'text', text: 'second' }] }] }
                  ]
                }
              ]
            }
          ]
        }
      ]
    };

    // when
    const back = fromProseMirror(json);
    const again = fromProseMirror(toProseMirror(back));

    // then: nothing is lost
    expect(again.blocks.map((block) => blockPlainText(block))).toEqual(['first', 'second']);
  });

  it('turns neighbouring spans with the same styling into one', () => {
    // given: ProseMirror often produces several bold runs in a row
    const json = {
      type: 'doc',
      content: [
        {
          type: 'paragraph',
          content: [
            { type: 'text', text: 'one ', marks: [{ type: 'bold' }] },
            { type: 'text', text: 'two', marks: [{ type: 'bold' }] }
          ]
        }
      ]
    };

    // when
    const back = fromProseMirror(json);

    // then
    expect(firstLine(back).spans).toHaveLength(1);
    expect(firstLine(back).spans[0]).toMatchObject({ text: 'one two', bold: true });
  });
});

describe('documents the editor may hand over', () => {
  it('produces one empty line for an empty editor', () => {
    // given / when
    const back = fromProseMirror({ type: 'doc', content: [{ type: 'paragraph' }] });

    // then
    expect(back.blocks).toHaveLength(1);
    expect(firstLine(back).type).toBe('paragraph');
    expect(firstLine(back).spans).toEqual([]);
  });

  it('never produces a document without lines', () => {
    // given / when / then
    expect(fromProseMirror({ type: 'doc', content: [] }).blocks).toHaveLength(1);
    expect(fromProseMirror(null).blocks).toHaveLength(1);
  });

  it('keeps the text of a node it does not model', () => {
    // given: something the schema grew later, e.g. a blockquote
    const json = {
      type: 'doc',
      content: [{ type: 'blockquote', content: [{ type: 'paragraph', content: [{ type: 'text', text: 'quoted' }] }] }]
    };

    // when
    const back = fromProseMirror(json);

    // then: the words are not lost
    expect(back.blocks).toHaveLength(1);
    expect(firstLine(back).spans).toEqual([{ text: 'quoted' }]);
  });
});
